        if (x.tagName !== 'A' || !x.getAttribute('href')) continue;
        let u; try { u = new URL(x.getAttribute('href'), oma); } catch (e) { continue; }
        const t = (/^\/fathers\/([^/]+)\.htm$/i.exec(u.pathname) || [])[1];
