    while (ylin.yla) ylin = ylin.yla;
    const versaali = ylin !== juuri && /\p{Lu}/u.test(ylin.nimi) && ylin.nimi === ylin.nimi.toUpperCase() && !/\d/.test(ylin.nimi) && ylin.nimi.split(/\s+/).length <= 4;
