    const tekija = rbMeta(document, 'DC.Creator.PersonalName').join(' & ');
    const vuosi = (/(1[0-9]\d\d|20\d\d)/.exec(rbMeta(document, 'DC.Date')[0] || '') || [])[1] || '';
