    if (m && k(m[2]) >= 0) return m[1] + '-' + String(k(m[2]) + 1).padStart(2, '0') + (m[3] ? '-' + m[3].padStart(2, '0') : '');
    m = /\b(\d{1,2})\s+([A-Z][a-z]{2})[a-z]*\.?\s+((?:19|20)\d\d)\b/.exec(s || '');
    if (m && k(m[2]) >= 0) return m[3] + '-' + String(k(m[2]) + 1).padStart(2, '0') + '-' + m[1].padStart(2, '0');
