  const KIRJE_EPAVARMA = /(?:^|[\s,\u2329\u3008\u27e8])(?:vor|nach|zwischen|um|ca\.|etwa|vermutlich|vmtl\.|wahrscheinlich|frühestens|spätestens|anfang|mitte|ende|oder)(?=[\s.]|$)/i;
