      while (n && (n.nodeType === 3 ? !n.nodeValue.trim() : n.tagName === 'BR')) { const x = n; n = puoli === 'firstChild' ? n.nextSibling : n.previousSibling; if (x.nodeType === 1) x.remove(); }
