    const pp = paikkaPvm.split(/\s+→\s+/)[0].replace(new RegExp('\\.?,?\\s+' + PR_VKP + '(?:\\s+\\p{L}+\\s+' + PR_VKP + ')?\\??(?=\\s*[\u232a\u3009\u27e9]|\\s*$)', 'u'), '');
