    'ha-del': 'del', 'ha-diagdel': 'del', 'ha-super': 'sup', 'ha-sub': 'sub', 'ha-added': ['[', ']'], 'ha-insertion': ['⸂', '⸃'], 'ha-nr': [' ◦', ' ◦'],
