    const ot = (ens.otsake || rivi(document.title)).replace(/(\(\d{4}\)).*$/, '$1').replace(/\s+(?:Book|Part|Chapter|Introduction|Preface)\b.*$/i, '').replace(/\s+pp?\.\s*[\d-]+.*$/i, '');
