      let ts = tk.sivu;
      for (let i = ti + 1; i < kohdat.length && kohdat[i].taso < 9; i++) if (kohdat[i].sivu != null) ts = Math.max(ts, kohdat[i].sivu);
      const pitkaTeos = tl != null ? tl - tk.sivu >= KO_RAJA : ts - tk.sivu >= KO_RAJA;
