          for (let i = ti + 1; i < kohdat.length && kohdat[i].taso < 9; i++) if (kohdat[i].taso === taso && kohdat[i].sivu != null && kohdat[i].sivu <= sivu) ki = i;
          if (ki < 0) continue;
