          if (!v || kaytetyt.has(id)) { if (!v) a.replaceWith(...a.childNodes); else a.remove(); return; }
          kaytetyt.add(id);
          const tunnus = 'ko' + (++laskuri);
          const vk = v.solu.cloneNode(true);
